class Solution {
    public String sortSentence(String sentence){
        String[] words=sentence.split(" "),result=new String[words.length];
        for(String word:words)result[word.charAt(word.length()-1)-'1']=word.substring(0,word.length()-1);
        return String.join(" ",result);
    }
}

code.kotlin:
class Solution {
    fun sortSentence(sentence:String):String{
        val words=sentence.split(' ');
        val result=Array(words.size){
            ""
        };
        for(word in words)result[word.last()-'1']=word.dropLast(1);
        return result.joinToString(" ")
    }
}

code.cpp:
class Solution {
    public: string sortSentence(string sentence){
        stringstream stream(sentence);
        vector<string> result(9);
        string word;
        int count=0;
        while(stream>>word){
            result[word.back()-'1']=word.substr(0,word.size()-1);
            ++count;
        }
        string answer;
        for(int i=0;i<count;++i){
            if(i)answer+=' ';
            answer+=result[i];
        }
        return answer;
    }
};
